void unit_test_update_non_head_node_all_fields_non_zero(void) {
    // Setup: create a linked list with at least two nodes
    // We'll use the insert function to build the list
    struct node *root = NULL;
    // Insert first node (ID 1)
    insert(&root, 1, 0, 5, 1);
    // Insert second node (ID 2) - this will be the non-head node we update
    insert(&root, 2, 1, 4, 2);
    // Insert third node (ID 3) to ensure we traverse
    insert(&root, 3, 2, 3, 3);

    // Verify initial state of node with ID 2 (non-head)
    struct node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: update non-head node (ID 2) with all non-zero values
    // This triggers path 6: head node check fails, traverse loop exits when ID matches,
    // then all three if conditions (ct != 0, wt != 0, tat != 0) are true
    update(&root, 2, 100, 50, 150);

    // Assertions: verify node with ID 2 was updated
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(100, ptr->CT);
    TEST_ASSERT_EQUAL_INT(50, ptr->WT);
    TEST_ASSERT_EQUAL_INT(150, ptr->TAT);

    // Verify other nodes unchanged
    ptr = root; // ID 1
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    ptr = root->next->next; // ID 3
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
}

// Test runner function (not main) to avoid multiple definition
void run_test_update_non_head_node_all_fields_non_zero(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_all_fields_non_zero);
    UNITY_END();
}

